class ExplorationController:
    """Open at most one independent branch per round, then refine in parallel."""
    def select(self, observed_nodes, round_index, workers, max_depth):
        parents = {node["parent"] for node in observed_nodes[1:]}
        leaves = [node for node in observed_nodes[1:]
                  if node["id"] not in parents and node["depth"] < max_depth
                  and not node.get("exhausted", False)]
        leaves.sort(key=lambda node: node["id"])
        batch = [node["id"] for node in leaves[:workers]]
        branches = sum(node["parent"] == 0 for node in observed_nodes[1:])
        if len(batch) < workers and branches < workers and not observed_nodes[0].get("exhausted", False):
            batch.append(0)
        return batch

class ExplorationController:
    """Open one root branch per round, then refine the best leaf in parallel."""
    def __init__(self):
        self.best_id = None
        self.best_score = 0.0
        self.last_len = 0

    def select(self, observed_nodes, round_index, workers, max_depth):
        if not observed_nodes:
            return []
        nodes = {node["id"]: node for node in observed_nodes}
        parents = {node.get("parent") for node in observed_nodes if node.get("id") != 0}
        # Track best revealed nonroot score for tie-break prioritization.
        for node in observed_nodes:
            nid = node.get("id")
            if nid == 0:
                continue
            score = node.get("score")
            if score is None:
                continue
            if self.best_id is None or score > self.best_score:
                self.best_score = score
                self.best_id = nid
        # Legal leaves: nonroot nodes with no child, depth < max_depth.
        leaves = []
        for node in observed_nodes:
            nid = node.get("id")
            if nid == 0:
                continue
            if nid in parents:
                continue
            if node.get("depth", 0) >= max_depth:
                continue
            leaves.append(nid)
        # Prefer leaves on the best-scoring branch (same root path), then by
        # descending score of the node itself, then descending id for depth.
        def key(nid):
            node = nodes[nid]
            path = []
            cur = nid
            while cur is not None and cur in nodes:
                path.append(cur)
                cur = nodes[cur].get("parent")
            on_best = 0 if (self.best_id is not None and self.best_id in path) else 1
            score = node.get("score")
            if score is None:
                score = -1e18
            return (on_best, -score, -node.get("depth", 0), nid)
        leaves.sort(key=key)
        batch = leaves[:max(0, workers)]
        # Open one new root branch per round while budget allows and root
        # has not been exhausted.
        if len(batch) < workers and not observed_nodes[0].get("exhausted", False):
            batch.append(0)
        return batch

