    def _signature(node):
        cand = node.get("candidate")
        if isinstance(cand, dict):
            return (cand.get("name"), cand.get("source"))
        return (None, None)

    def select(self, observed_nodes, round_index, workers, max_depth):
        if not observed_nodes:
            return []
