            limit = int(workers)
        except Exception:
            limit = 0
        if limit <= 0:
            return []

        nodes = {}
        for node in observed_nodes:
            nid = node.get("id")
            if nid is not None:
                nodes[nid] = node
        if 0 not in nodes:
