            if nid is None or nid == 0:
                continue
            score = node.get("score")
            if score is None:
                continue
            if score > self.best_score:
                self.best_score = score

        # Count only newly revealed, genuinely novel nonroot candidates as
        # generation calls.  A node observed for the first time whose
        # candidate is a duplicate of an earlier one is a clone: it consumed
        # no new generation.  Reselecting a previously seen node is a replay
        # round and is also free of generation cost.
        for node in observed_nodes:
            nid = node.get("id")
            if nid is None or nid == 0:
                continue
            if nid in self.seen_revealed:
                continue
            self.seen_revealed.add(nid)
            sig = self._signature(node)
            if sig == (None, None) or sig in self.previous_candidates:
                continue
            self.previous_candidates.add(sig)
            self.selected_counts[nid] = self.selected_counts.get(nid, 0) + 1

        # Stall detection against the best revealed score.
        if self.best_score > self.prev_best + 1e-15:
            self.prev_best = self.best_score
            self.stalled_rounds = 0
        else:
            self.stalled_rounds += 1

        # Legal leaves: nonroot, no child, depth < max_depth.
        leaves = []
        for node in observed_nodes:
            nid = node.get("id")
            if nid is None or nid == 0:
                continue
            if nid in parents:
                continue
            try:
                depth = node.get("depth", 0)
                if depth is None:
