            path = []
            cur = nid
            seen = set()
            while cur is not None and cur in nodes and cur not in seen:
                seen.add(cur)
                path.append(cur)
                cur = nodes[cur].get("parent")
            return path

        # Best root branch by best score observed on that branch.
        branch_best = {}
        for nid in leaves:
            path = path_of(nid)
            root_child = path[-1] if len(path) >= 2 else None
            if root_child is None:
                continue
            sc = nodes[nid].get("score")
            sc = sc if sc is not None else -1e18
            if root_child not in branch_best or sc > branch_best[root_child]:
                branch_best[root_child] = sc
        best_branch = None
        if branch_best:
            best_branch = max(branch_best, key=lambda bc: (branch_best[bc], -bc))

        def key(nid):
            node = nodes[nid]
            path = path_of(nid)
            root_child = path[-1] if len(path) >= 2 else None
            on_best = 0 if (root_child is not None and root_child == best_branch) else 1
            score = node.get("score")
            score = score if score is not None else -1e18
            st = node.get("stagnation") or 0
            fs = node.get("failure_streak") or 0
            depth = node.get("depth", 0) or 0
