        batch = []
        seen_ids = set()
        # Never select an exhausted leaf unless no unexhausted legal action
        # exists anywhere: replay rounds reveal nothing and inflate N.
        for nid in leaves:
            if len(batch) >= limit:
                break
            if nodes[nid].get("exhausted", False):
                continue
            if nid in seen_ids:
                continue
            seen_ids.add(nid)
            batch.append(nid)
